// renderPriceMonitorPage 按 lang 渲染整张分享页（仍是一个自包含的页面）。lang 与查询接口用同一套
// 解析（i18n.GetLangFromContext），页面脚本查询时也带上同一个 Accept-Language，所以界面文字、
// 固定来源的表头名称与阶梯档位说明始终是同一种语言；日期与金额也按它格式化。
func renderPriceMonitorPage(lang, logo string) string {
	texts := make(map[string]string, len(priceMonitorPageEntries))
	pairs := make([]string, 0, 2*len(priceMonitorPageEntries)+6)
	for _, entry := range priceMonitorPageEntries {
		text := i18n.Translate(lang, entry.key, entry.args)
		texts[entry.name] = text
		pairs = append(pairs, "__T_"+entry.name+"__", html.EscapeString(text))
	}
	encoded, err := marshalPriceMonitorPageText(texts)
	if err != nil {
		encoded = "{}"
	}
	pairs = append(pairs, "__I18N__", encoded, "__LANG__", lang, "__LOGO_SRC__", html.EscapeString(logo))
	return strings.NewReplacer(pairs...).Replace(priceMonitorHTML)
}

// marshalPriceMonitorPageText 把文字编码成放进 <script> 的 JSON。common.Marshal 会把 <、>、&
// 转义成 < 这类形式，文字里即便出现 </script> 也不会提前闭合标签。
func marshalPriceMonitorPageText(value any) (string, error) {
	encoded, err := common.Marshal(value)
	return string(encoded), err
}
